package com.bank.processing;

// Base processor. Declares BOTH a static and an instance tier method.
class AccountProcessor {

    // STATIC: resolved by the DECLARED reference type (compile-time binding).
    static String tierStatic() {
        return "BASE tier (static — bound to declared type)";
    }

    // INSTANCE: resolved by the RUNTIME object (dynamic dispatch).
    String tierInstance() {
        return "BASE tier (instance — dynamic dispatch)";
    }
}
