package com.bank.processing;

// Child processor. The static method HIDES; the instance method OVERRIDES.
class SavingsProcessor extends AccountProcessor {

    // HIDES the base static method (NOT an override — @Override would not compile).
    static String tierStatic() {
        return "SAVINGS tier (static — hides base, reached only via Savings type)";
    }

    // OVERRIDES the base instance method (dynamic dispatch picks this at runtime).
    @Override
    String tierInstance() {
        return "SAVINGS tier (instance — override wins via dynamic dispatch)";
    }
}
