package com.bank.processing;

import java.util.logging.*;

public class StaticHidingDemo {
    private static final Logger log = Logger.getLogger(StaticHidingDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Declared type = AccountProcessor, runtime object = SavingsProcessor.
        AccountProcessor ref = new SavingsProcessor();

        // STATIC call through the reference: compiler uses the DECLARED type.
        // Even though the object is a SavingsProcessor, this prints BASE.
        String staticResult = ref.tierStatic(); // style warning: call via class name
        log.info(() -> "Static via parent ref  -> " + staticResult);

        // INSTANCE call through the same reference: JVM uses the RUNTIME object.
        // This prints SAVINGS because of dynamic dispatch.
        String instanceResult = ref.tierInstance();
        log.info(() -> "Instance via parent ref-> " + instanceResult);

        // Proof: calling the static method via each class name reaches each version.
        log.info(() -> "AccountProcessor.tierStatic() -> " + AccountProcessor.tierStatic());
        log.info(() -> "SavingsProcessor.tierStatic() -> " + SavingsProcessor.tierStatic());
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
